import{_ as e,o,c as n,a2 as a}from"./chunks/framework.Dhf_H6O0.js";const u=JSON.parse('{"title":"Connecting Your Tools","description":"","frontmatter":{},"headers":[],"relativePath":"connecting-tools/overview.md","filePath":"connecting-tools/overview.md"}'),s={name:"connecting-tools/overview.md"};function r(l,t,i,p,c,d){return o(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="connecting-your-tools" tabindex="-1">Connecting Your Tools <a class="header-anchor" href="#connecting-your-tools" aria-label="Permalink to &quot;Connecting Your Tools&quot;">​</a></h1><p>Once the gateway is running, each enabled MCP server is available as an HTTP endpoint. Your AI tools connect to these endpoints using standard OpenAPI URLs.</p><h2 id="where-to-find-the-urls" tabindex="-1">Where to find the URLs <a class="header-anchor" href="#where-to-find-the-urls" aria-label="Permalink to &quot;Where to find the URLs&quot;">​</a></h2><ol><li>Go to <strong>Home</strong> (Dashboard).</li><li>Switch to the <strong>Clients</strong> tab.</li><li>You&#39;ll see a table with one row per enabled server.</li></ol><p>Each row provides:</p><table tabindex="0"><thead><tr><th>Button</th><th>What it copies</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Copy base</strong></td><td><code>http://localhost:8000/telecontext</code></td><td>When your tool asks for a &quot;base URL&quot; or &quot;server URL&quot;</td></tr><tr><td><strong>Copy OpenAPI</strong></td><td><code>http://localhost:8000/telecontext/openapi.json</code></td><td>When your tool asks for an &quot;OpenAPI spec URL&quot; — this is the most common</td></tr><tr><td><strong>Copy OpenAPI JSON</strong></td><td>The raw OpenAPI JSON spec</td><td>When you need the full spec content, not just the URL</td></tr><tr><td><strong>Open docs</strong></td><td>—</td><td>Opens interactive API documentation in your browser</td></tr></tbody></table><h3 id="bulk-copy" tabindex="-1">Bulk copy <a class="header-anchor" href="#bulk-copy" aria-label="Permalink to &quot;Bulk copy&quot;">​</a></h3><p>Below the table, expand <strong>&quot;Bulk copy — all servers at once&quot;</strong> to copy all base URLs or all OpenAPI JSON URLs in one click. Useful if you have many servers.</p><h2 id="url-format" tabindex="-1">URL format <a class="header-anchor" href="#url-format" aria-label="Permalink to &quot;URL format&quot;">​</a></h2><p>The gateway runs on <code>http://localhost:8000</code> by default (configurable in <a href="./../settings/gateway-docker.html">Settings</a>). Each server gets its own path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:{port}/{server-name}</span></span>
<span class="line"><span>http://localhost:{port}/{server-name}/openapi.json</span></span></code></pre></div><p>For example, with port 8000 and a server named <code>telecontext</code>:</p><ul><li>Base URL: <code>http://localhost:8000/telecontext</code></li><li>OpenAPI spec: <code>http://localhost:8000/telecontext/openapi.json</code></li></ul><h2 id="supported-clients" tabindex="-1">Supported clients <a class="header-anchor" href="#supported-clients" aria-label="Permalink to &quot;Supported clients&quot;">​</a></h2><p>Any tool that supports <strong>OpenAPI tool definitions</strong> or <strong>MCP over HTTP</strong> can connect. Common examples:</p><ul><li><strong>Open WebUI</strong> — see the <a href="./open-webui.html">detailed guide</a></li><li><strong>LangChain / LangGraph</strong> — use the OpenAPI URL as a tool source</li><li><strong>Custom applications</strong> — call the endpoints directly with HTTP</li></ul><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Follow the <a href="./open-webui.html">Open WebUI integration guide</a> for step-by-step instructions.</p>`,18)])])}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
